'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/snackbar/md-gb-snackbar.js';
import '@material/web/labs/gb/components/snackbar/md-gb-snackbar-host.js';
import {SnackbarElement} from '@material/web/labs/gb/components/snackbar/snackbar-element.js';
import {SnackbarHostElement} from '@material/web/labs/gb/components/snackbar/snackbar-host-element.js';

/**
 * A Material Design snackbar component. Wraps <md-gb-snackbar>.
 * Docs: https://material-web.dev/3.0/components/snackbar/
 */
export const MdSnackbar = createComponent({
  react: React,
  tagName: 'md-gb-snackbar',
  elementClass: SnackbarElement,
  events: {
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
  },
});

export type MdSnackbarProps = React.ComponentProps<typeof MdSnackbar>;

/**
 * Shows queued snackbars one at a time. Wraps <md-gb-snackbar-host>.
 * Docs: https://material-web.dev/3.0/components/snackbar/
 */
export const MdSnackbarHost = createComponent({
  react: React,
  tagName: 'md-gb-snackbar-host',
  elementClass: SnackbarHostElement,
  events: {
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
  },
});

export type MdSnackbarHostProps = React.ComponentProps<typeof MdSnackbarHost>;
